client_script:
// -------------------- WEB FORM SCRIPT --------------------
if (frappe.web_form) {
    // When ticket is selected in Attendees child table
    frappe.web_form.on('attendes', {
        ticket: function(frm, cdt, cdn) {
            let row = locals[cdt][cdn];
            if (row.ticket) {
                frappe.db.get_value('Festa Ticket Type', row.ticket, ['price', 'currency'], (r) => {
                    if (r) {
                        row.price = r.price || 0;
                        row.currency = r.currency || "USD";
                        frappe.web_form.refresh_field('attendes');
                        update_total_amount();
                    }
                });
            }
        },
        price: function(frm, cdt, cdn) {
            update_total_amount();
        }
    });

    // Utility function to recalc total
    function update_total_amount() {
        let total = 0;
        (frappe.web_form.doc.attendes || []).forEach(row => {
            total += flt(row.price);
        });
        frappe.web_form.set_value("total_amount", total);
    }
}

// -------------------- DESK FORM SCRIPT --------------------
frappe.ui.form.on("Festa Event", {
    refresh(frm) {
        // Add Pay Now button if event is published & scheduled
        if (frm.doc.is_published && frm.doc.status === "Scheduled") {
            frm.add_custom_button(__("Pay Now"), () => {
                frappe.call({
                    method: "vyshuwa.vyshuwa.api.api.create_payment_request",
                    args: { docname: frm.doc.name },
                    callback: function(r) {
                        if (r.message) {
                            frappe.msgprint(__("Payment Request Created: ") + r.message);
                            // Redirect to payment page
                            window.location.href = `/payment-request/${r.message}`;
                        }
                    }
                });
            }, __("Action")).addClass("btn-success");
        }
    }
});

custom_css:
/* --- Web Form Styling --- */
.web-form {
  max-width: 700px;
  margin: 40px auto;
  background: #fff;
  padding: 30px;
  border-radius: 16px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.08);
  font-family: "Inter", "Segoe UI", sans-serif;
}

/* Heading */
.web-form h2,
.web-form .form-section h2 {
  font-size: 1.5rem;
  font-weight: 600;
  margin-bottom: 20px;
  color: #333;
  border-bottom: 2px solid #eee;
  padding-bottom: 8px;
}

/* Form groups */
.web-form .form-group {
  margin-bottom: 20px;
}

.web-form label {
  display: block;
  font-weight: 500;
  margin-bottom: 6px;
  color: #444;
}

/* Inputs, selects, textareas */
.web-form input[type="text"],
.web-form input[type="email"],
.web-form input[type="date"],
.web-form input[type="number"],
.web-form input[type="password"],
.web-form select,
.web-form textarea {
  width: 100%;
  padding: 10px 14px;
  border: 1px solid #ddd;
  border-radius: 10px;
  font-size: 0.95rem;
  transition: border 0.2s, box-shadow 0.2s;
}

.web-form input:focus,
.web-form select:focus,
.web-form textarea:focus {
  border-color: #4f46e5;
  box-shadow: 0 0 0 3px rgba(79,70,229,0.15);
  outline: none;
}

/* Buttons */
.web-form .btn {
  display: inline-block;
  background: #4f46e5;
  color: #fff !important;
  padding: 12px 24px;
  font-size: 1rem;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.web-form .btn:hover {
  background: #4338ca;
}

.web-form .btn:active {
  transform: scale(0.98);
}

/* Table (Attendees field) */
.web-form table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 10px;
}

.web-form table th,
.web-form table td {
  border: 1px solid #eee;
  padding: 10px;
  text-align: left;
}

.web-form table th {
  background: #f9fafb;
  font-weight: 600;
}

.web-form table td input,
.web-form table td select {
  width: 100%;
  border: none;
  background: transparent;
  padding: 6px;
}

/* Total Amount */
.web-form .form-group:last-of-type {
  border-top: 1px dashed #ddd;
  padding-top: 20px;
  margin-top: 30px;
}
